-- Migration: add the `guest_tokens` table (invite-only /address gate).
-- The /address page is reachable ONLY through personal links texted to
-- guests; GET /api/address/validate and POST /api/address both check
-- tokens against this table. Tokens are generated by
-- scripts/import_guests.mjs (--sync inserts them here).
-- Existing databases: apply this file alone, e.g.
--   psql "$DATABASE_URL" -f migrations/002_add_guest_tokens.sql
-- (Fresh databases can simply run schema.sql, which includes this table.)

CREATE TABLE IF NOT EXISTS guest_tokens (
  token text PRIMARY KEY,
  guest_name text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);

-- The two personal links already texted out. Idempotent: safe to re-run.
INSERT INTO guest_tokens (token, guest_name) VALUES
  ('e8sakufe', 'Zach'),
  ('h4zxhqe7', 'Kendra')
ON CONFLICT (token) DO NOTHING;
